/// <summary>
/// AVA
/// </summary>
/// <returns>AmountCur</returns>
protected AmountCur calculateFreeValue()
{
    real ret;
    CustTable						custTable  = CustTable::find(this.invoiceAccount());

    ret = next calculateFreeValue();

    //ret   = custTable.CreditMax - AVAFCMGroupTable::getInvoicedAmountWithoutTaxesByCustTable(custTable);
    ret   = custTable.CreditMax - AVAFCMGroupTable::getInvoicedAmountWithoutTaxesWithMarkupsByCustTable(custTable);
    freeValue = ret;

    return ret;

}
